 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    row_seps = [r for r in range(h) if len(set(grid[r])) == 1]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def blocks(length, seps):
        starts = []
        prev = 0
        for s in seps:
            if prev < s:
                starts.append((prev, s))
            prev = s + 1
        if prev < length:
            starts.append((prev, length))
        return starts

    rb = blocks(h, row_seps)
    cb = blocks(w, col_seps)
    sep_colors = {grid[r][0] for r in row_seps} | {grid[0][c] for c in col_seps}
    counts = {}
    for r0, r1 in rb:
        for c0, c1 in cb:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    if v not in sep_colors:
                        counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    marker = next(v for v in counts if v != background)
    out = []
    for r0, r1 in rb:
        row = []
        for c0, c1 in cb:
            n = sum(grid[r][c] == marker for r in range(r0, r1) for c in range(c0, c1))
            row.append(1 if n == 2 else background)
        out.append(row)
    return out
